import os
import zipfile
import io
from flask import Flask, request, jsonify

app = Flask(__name__)


def extract_text_from_zip(zip_bytes):
    """Extract and concatenate contents of all text files from a zip archive."""
    text_parts = []
    try:
        with zipfile.ZipFile(io.BytesIO(zip_bytes), 'r') as zf:
            for name in zf.namelist():
                if name.endswith('.txt'):
                    try:
                        content = zf.read(name).decode('utf-8')
                        text_parts.append(content)
                    except (UnicodeDecodeError, LookupError):
                        # Skip files that can't be decoded as UTF-8
                        continue
    except zipfile.BadZipFile:
        raise ValueError("Invalid zip file")
    return '\n'.join(text_parts)


@app.route('/convert', methods=['POST'])
def convert():
    """Convert a zip file to a text file."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not file.filename.endswith('.zip'):
        return jsonify({'error': 'File must be a zip file'}), 400

    try:
        zip_bytes = file.read()
        if not zip_bytes:
            return jsonify({'error': 'Empty file'}), 400

        text_content = extract_text_from_zip(zip_bytes)

        if not text_content.strip():
            return jsonify({'error': 'No text files found in zip'}), 400

        return text_content, 200, {'Content-Type': 'text/plain'}

    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
